<?php require __DIR__.'/../config/bootstrap.php';$p=db();$s=$p->query('SELECT id,tenant_id,name,device_id FROM (SELECT d.id,d.tenant_id,d.name,d.id device_id,d.last_seen_at FROM devices d WHERE d.status="active" AND (d.last_seen_at IS NULL OR d.last_seen_at<NOW()-INTERVAL 15 MINUTE)) x');foreach($s as $d){$q=$p->prepare('SELECT COUNT(*) c FROM alerts WHERE tenant_id=? AND device_id=? AND status="open" AND title="Dispositivo offline"');$q->execute([$d['tenant_id'],$d['id']]);if(!(int)$q->fetch()['c']){$i=$p->prepare('INSERT INTO alerts(tenant_id,device_id,severity,title,message) VALUES(?,?,?,?,?)');$i->execute([$d['tenant_id'],$d['id'],'warning','Dispositivo offline','O dispositivo '.$d['name'].' não comunica há mais de 15 minutos.']);}}
